 const AB=/\b(?:do(?:es)?\s+not|did\s+not|doesn['’]t|didn['’]t|never)\s+(?:deny|denies|dispute|contradict|exclude|rule\s+out|name|state|say|mention|specify|forbid|reject|tell|record)\b|\bnames?\s+no\b|\bstates?\s+no\b|\bsays?\s+nothing\b|\bno\s+(?:verse|row|text|word|witness)s?\s+(?:(?:that|which)\s+)?(?:states?|says?|names?|denies|deny|excludes?)\b|\bis\s+silent\b|\bwithout\s+(?:asserting|stating|naming|saying|mentioning|specifying|denying|excluding)\b|\b(?:is|are|was|were)\s+(?:itself\s+|themselves\s+)?not\s+(?:itself\s+|themselves\s+)?(?:denied|contradicted|excluded|ruled\s+out|named|stated)\b/i;
 const REF=/(?:[1-3]\s)?[A-Z][a-z]+\.?\s\d{1,3}:\d{1,3}/;
 const W=s=>String(s||'').toLowerCase().replace(/[‘’]/g,"'").replace(/[^a-z0-9' ]+/g,' ').replace(/\s+/g,' ').trim();
 const unq=s=>String(s||'').replace(/"[^"\n]*"|“[^”\n]*”/g,' " ');

 const ROUNDS=['CR2','DR1','DR2','CR3','DR3','CR4','DR4'];
 const GIVE=/\bI\s+(?:drop|withdraw|narrow|grant|concede|accept|allow|rest\s+(?:nothing|on\s+no))\b|\bnarrow\s+(?:accordingly|it|the\s+link)\b|^\W*(?:Granted|Conceded|CONCEDED|Grant)\b|\bI\s+do\s+not\s+(?:say|claim|rest|hold|argue)\b|\bno\s+longer\s+(?:claims?|holds?|rests?)\b|\bin\s+(?:so\s+many\s+)?words\b|\bI\s+hold\s+(?:that|this|the)\s+limb\b/i;
 const AG=/\bagainst\s+[CD]\d/i;const ANS=/\banswers?\s+to\b|^[\s#>*_-]*ANSWER\s*:|\bpressed\s+rows\b|\banswers?\s+(?:on|for)\s+the\s+press/i;
 function blocks(t){const L=String(t||'').split('\n');const out=[];let off=0,cur=null;
  const md=l=>{const m=l.match(/^\s*(#{1,6})\s/);return m?m[1].length:0;};const bold=l=>/^\s*\*\*[^*\n]{2,200}\*\*\s*:?\s*$/.test(l)||/^\s*[A-Z][A-Za-z' -]{2,40}:\s*$/.test(l);const link=l=>/^[\s#>*_-]*LINK\s+\d+\b/i.test(l);const rule=l=>/^\s*-{3,}\s*$/.test(l);
  for(const l of L){const a=off;off+=l.length+1;const lv=md(l);
   if(cur){const end=cur.md?((lv&&lv<=cur.md)||(cur.md>1&&rule(l))):(lv||rule(l)||link(l)||bold(l));if(end||cur.ag&&ANS.test(l)){cur.e=a;out.push(cur);cur=null;}}
   if(!cur&&(lv||bold(l)||/^[\s>*_-]*\**\s*ANSWER\s*:/i.test(l))&&(ANS.test(l)||AG.test(l)))cur={s:a,md:lv,head:l.trim().slice(0,80),ag:!ANS.test(l)};}
  if(cur){cur.e=off;out.push(cur);}return out;}
 function harvest(R){const out=[];const seen=new Set();
  for(const k of ROUNDS){const t=String(R&&R[k]||'');if(!t)continue;const BL=blocks(t);if(!BL.length)continue;const inA=i=>BL.some(b=>i>=b.s&&i<b.e);let off=0;
   for(const para of t.split(/(\n)/)){const at=off;off+=para.length;if(!para.trim()||/^\s*#|^\s*\**\s*LINK\s+\d+\s*:\s*\**\s*\w+\**\s*$|^\s*\*\*[^*\n]{2,200}\*\*\s*:?\s*$|^\s*[A-Z][A-Za-z' -]{2,40}:\s*$/i.test(para.trim()))continue;
    let so=0;for(const s0 of para.split(/(?<=[.!?]["”']?)\s+(?=["“(\[*]*[A-Z])/)){const pos=at+para.indexOf(s0,so);so=Math.max(so,pos-at+s0.length);
     const s=s0.replace(/\s+/g,' ').replace(/^[\s*_\-•]+|[\s*_]+$/g,'').trim();if(s.length<12||/^(?:PRESSED WITH|MEANS)\b/i.test(s))continue;
     if(!inA(pos))continue;const m=unq(s).match(AB);if(!m||GIVE.test(unq(s))||BL.some(b=>b.ag&&pos>=b.s&&pos<b.e)&&!/^no\s/i.test(m[0]))continue;if(!REF.test(t.slice(Math.max(0,pos-600),pos+s0.length)))continue;
     const key=k+'|'+W(s);if(seen.has(key))continue;seen.add(key);const bl=BL.find(b=>pos>=b.s&&pos<b.e);out.push({id:'I'+(out.length+1),round:k,side:k[0]==='C'?'DEFENDER':'CHALLENGER',sentence:s.slice(0,400),phrase:m[0],block:bl?bl.head:null});}}}
  return out;}

 const LINE=/^[\s>*_\-•]*IMPOSED\s*:\s*\[\s*((?:CR|DR)[1-4])\s*\]\s*["“]([\s\S]+?)["”]\s*--\s*(?:asks\s+([\s\S]+?)\s+to\s+([\s\S]+?)\s*--\s*(NO ROW SETS IT|SET BY\b\s*([\s\S]*))|(NOT A REQUIREMENT)\s*--\s*rebuts\s*\[\s*((?:CR|DR)[1-4])\s*\]\s*["“]([\s\S]+?)["”])\s*$/i;

 function rebutOk(l,round,R){if(!l||!l.nar)return {ok:false,why:'not a NOT A REQUIREMENT line'};if(l.rround[0]===round[0])return {ok:false,why:'['+l.rround+'] is a round of the same side; a rebuttal answers the other side'};
  const q=W(l.rquote);if(q.split(' ').length<6)return {ok:false,why:'the rebutted quote has fewer than 6 words'};if(!R||!R[l.rround])return {ok:false,why:'round ['+l.rround+'] could not be read'};
  if(!W(R[l.rround]).includes(q))return {ok:false,why:'the quote does not stand word for word in ['+l.rround+']'};return {ok:true,why:'rebuts ['+l.rround+'] "'+String(l.rquote).slice(0,80)+'", which stands in that round'};}
 const RND=/^===\s*\[(CR[1-4]|DR[1-4])\][^\n]*===\s*$/gm;


 const AC=/^[\s>*_\-•]*ANSWER CHECK\s*:\s*([^\n]*?)\s*--\s*\[\s*((?:CR|DR)[1-4])\s*\]\s*--[\s\S]*?ANSWER\s*:\s*["“]([\s\S]*?)["”]\s*--\s*(MEETS|MISSES|FAILS)\b/i;



 return {AB,GIVE,blocks,harvest,rebutOk,};})();
const BAR=(()=>{
 const W=s=>String(s||'').toLowerCase().replace(/[‘’]/g,"'").replace(/[^a-z0-9' ]+/g,' ').replace(/\s+/g,' ').trim();
 const NAR=/NOT A REQUIREMENT\s*--\s*rebuts\s*\[\s*((?:CR|DR)[1-4])\s*\]\s*["“]([\s\S]+?)["”]/i;
 const MARK='[VOID (pkgBAR): a barred move struck by the system. The press this answered counts as unanswered.]';
 const esc=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
 function loc(raw,s){const t=String(raw||'');const w=String(s||'').trim().split(/\s+/).filter(Boolean);if(!w.length)return null;
  const re=new RegExp(w.map(esc).join('[\\s*_]+'));const m=t.match(re);return m?{i:m.index,len:m[0].length}:null;}
 const move=s=>/\b(?:needs?|requires?|must|would\s+have\s+to|has\s+to)\b/i.test(s)
  ?{code:'b',name:'BARRED MOVE (b), a requirement the verse never sets'}:{code:'a',name:'BARRED MOVE (a), an answer from silence'};
 function check(round,raw,R){const out={applies:true,round,hits:[],rebutted:[]};const t=String(raw||'');if(!t){out.applies=false;return out;}
  const H=IMP.harvest({[round]:t});
  for(const h of H){const at=loc(t,h.sentence);let nar=null;
   if(at){const tail=t.slice(at.i).split('\n').slice(0,3).join('\n');const m=tail.match(NAR);
    if(m){const v=IMP.rebutOk({nar:true,rround:m[1].toUpperCase(),rquote:m[2]},round,R||{});nar={rround:m[1].toUpperCase(),rquote:m[2],ok:v.ok,why:v.why};}}
   const x={id:'B'+(out.hits.length+out.rebutted.length+1),round,sentence:h.sentence,phrase:h.phrase,block:h.block,move:move(h.sentence),found:!!at,nar};
   (nar&&nar.ok?out.rebutted:out.hits).push(x);}
  out.pass=!out.hits.length;return out;}
 function note(c){return "BARRED MOVES CHECK -- computed by the system from your round, not by a model. Each sentence below answers from what a verse does not name, state, say or deny. That is a barred move (BARRED MOVES, your instructions).\n"
  +"Write your whole round again, the same case in the same words, but replace each sentence below with a positive answer: quote the words a verse does state ([L1], with its reference) and say what they carry. "
  +"If a sentence only denies a requirement that the other side imposed, you may keep it and write directly under it the line NOT A REQUIREMENT -- rebuts [<the other side's round>] \"<their words, 6 or more, word for word>\". "
  +"A sentence that still answers from silence in the round you return is VOID: the system strikes it from the round, the press it answered counts as unanswered, and the offense is named in the run report. The sentences:\n"
  +c.hits.map(h=>h.id+' ['+h.round+'] "'+h.sentence+'" -- '+h.move.name+(h.nar&&!h.nar.ok?' (your NOT A REQUIREMENT line does not verify: '+h.nar.why+')':'')).join('\n')
  +"\nReturn the whole round; this is the only request of its kind. Repeated offenses will result in disqualification.";}


 return {check,note,loc,move,MARK,NAR};})();
const LAY=(()=>{ 
 const LIM=['at all','only','never','none','all','alone','solely','any','every','no','entirely','wholly','exclusively','always','nothing','without'];
 const NEG=/\b(?:not|no|neither|nor|none)\b/i;const NEGW=['no','none','any'];const WIDEN=['only','alone','solely'];const TXT=/^(?:bible|bibles|record|kjv|text|debate|canon|book)\b/;const DESC=/^(?:stated|states|state|named|names|written|writes|record|record's|text|text's|says|speaks|carrying|carries|register|narrate|narrates|narrated|narrating|naming|saying|telling|tells|told)$/;  
 const W=s=>' '+String(s||'').toLowerCase().replace(/[‘’']/g,"'").replace(/[^a-z' ]+/g,' ').replace(/\s+/g,' ').trim()+' ';
 const REFS='(?:[1-3]\\s)?[A-Z][a-z]+(?:\\sof\\s[A-Z][a-z]+)?\\.?\\s\\d{1,3}:\\d{1,3}';const REFG=new RegExp(REFS,'g');
 const CP=/^[\s#>*_-]*(?:(?:\d{1,2}|[IVX]{1,5})[.)]\s*[*_]*\s*)?(?:LINK\s+(?:[A-Z]?\d+|[A-Z])\b|C\d+\s*(?:=|--|:|—|–|\.(?!\d)|\(|AGAINST\b)|[CD]\d+\s+(?:\(?kept\)?|SUPPORTED)\b|[CD]\d+[*_]+\s|(?:Answer|ANSWER)\b[^\n]{0,40}\bpress|PREMISE\s+\d+\b|D\d+\s*(?:--|:|—|–|\.(?!\d)|\()|PRESS(?:ES)?\b)|^\s*#{1,6}\s*[*_]*\s*(?:(?:\d{1,2}|[IVX]{1,5})[.)]|Point\s+\d+\b)/i;    const MD=/^\s*#{1,6}\s/;const WD=/\b(?:correction|corrects?|correcting|withdraw(?:s|n|al|ing)?|withdrew|retract(?:s|ed|ion|ing)?)\b/i,WDN=/\b(?:not|no|never|nor|cannot)\s+(?:\w+\s+){0,2}(?:correct|withdr|retract)/i;
 const Q=/["“]([^"”\n]{6,})["”]/g;
 const RECAP=/\b(?:the\s+)?(?:defender|challenger)\s+wrote\b/i;
 const CR=/MEANS\s*\[CR\d+\]/;const BK=/\bquoted\s+above\b/i;  
 const ABS=/\b(?:do(?:es)?|did)\s+not\s+(?:state|say|name|record|mention|give|call|write|speak|show|carry|narrate|deny)\b|\b(?:never|nowhere)\s+(?:states?|says?|names?|records?|mentions?|calls?|gives?|shows?|carr(?:y|ies)|narrates?)\b|\b(?:is|are|was)\s+(?:not|never)\s+(?:stated|named|recorded|written|given|said|shown)\b|\bsilent\b/i;
 const CONC=/\b(?:therefore|thus|hence|so\s+(?:the|it|he|she|they|his|her|this|that|then|a|an)|which\s+(?:means|proves|shows)|meaning\s+that|proves?|proving|it\s+follows|establish(?:es|ed)?)\b|\bso\s*,/i;
 const LBL=/^[\W_]*(?:(?:LINK\s+[A-Z]?\d+|[CD]\d+|PREMISE\s+\d+|Point\s+\d+)[\W_]*)?(?:SUPPORTED|UNSUPPORTED|KEPT|ANSWERED)?[\W_]*$/i;

 function absent(x){const S=x.split(/\n+|(?<=[.;!?])\s+(?=[A-Z\[*#"“])/).map(s=>s.replace(/[*_#>`]/g,'').trim()).filter(s=>s&&!LBL.test(s));if(!S.length||CONC.test(x))return false;return S.every(s=>ABS.test(s)&&new RegExp(REFS).test(s));}

 function words(t){const out=[];for(const l of String(t||'').split('\n')){if(CR.test(l))continue;const m=l.match(/MEANS\s*:\s*(.*?)(?:\s--\s|\s\|\s|$)/);if(!m)continue;
   const GOV=/\b(?:claim|claims|verdict|verdicts|defender|defender's|challenger|challenger's|argument|opponent|opponent's)\b/i;  
   const before=l.slice(0,l.indexOf(m[0]));if(/press/i.test(before))continue;if(/^\s*["“]/.test(m[1]))continue;const vq=[...before.matchAll(Q)].map(x=>x[1]);if(!vq.length)continue;
   const mi=l.indexOf(m[0]),after=l.slice(mi+m[0].length);const l3=[...after.matchAll(Q)].map(x=>x[1]); 
   const ct=vq.concat(l3).join(' ');const carried=W(ct);const neg=NEG.test(ct);let means=W(m[1].split(/[,;:()]|\s--\s|\s[—–]\s/).filter(x=>!GOV.test(x)).join(' , '));const add=[];
   if(means.includes(' at all ')&&!carried.includes(' at all ')){add.push('at all');}means=means.split(' at all ').join(' ');const mw=means.trim().split(' ');
   for(const w of LIM){if(w==='at all')continue;if(carried.includes(' '+w+' ')||(neg&&NEGW.includes(w)))continue;
     let hit=false;mw.forEach((x,i)=>{if(x!==w)return;const pre=mw.slice(Math.max(0,i-6),i);if(WIDEN.includes(w)&&pre.includes('not'))return; if(TXT.test(mw.slice(i+1,i+2).join(' ')||''))return; if(mw.slice(Math.max(0,i-3),i+6).some(y=>DESC.test(y)))return; hit=true;});if(hit)add.push(w);}
   if(add.length)out.push({kind:'WORDS',add,line:l.trim().slice(0,600),why:'the MEANS adds '+add.map(x=>'"'+x+'"').join(', ')+', which no KJV words of a verse quoted on that row carry'});}return out;}

 const R1=new RegExp(REFS,'g'),QO=/["“][^"”\n]{6,}["”]/,ANS=new RegExp('^[\\s*_>-]*ANSWER\\s*:\\s*('+REFS+')[^\\n]{0,40}?(?:--|—)\\s*D\\d+\\s*(?:--|—)[\\s*]*["“][^"”\\n]{6,}["”]'),MR=new RegExp('^[\\s*_>-]*(?:\\[L1\\][\\s*]*)?('+REFS+')[\\s:,*]*["“][^"”\\n]{6,}["”][^\\n]*?\\sMEANS\\s*:');
 const nr=v=>v.replace(/\s+/g,' ').replace(/\.(?=\s)/,'');
 function paired(seg,RW,l4){const out=[];const ms=[...seg.matchAll(R1)];ms.forEach((m,k)=>{const end=m.index+m[0].length,stop=k+1<ms.length?ms[k+1].index:seg.length;const t=seg.slice(end,stop);const qi=t.search(QO);if(qi>=0&&qi<=160&&!/\)/.test(t.slice(0,qi))){if(credit(m[0],t.slice(qi).match(QO)[0],t,RW,l4))out.push(nr(m[0]));return;}const pre=seg.slice(0,m.index);if(/["”][\s,]*\([^()\n]{0,40}$/.test(pre)){const qs=pre.match(new RegExp(QO.source,'g'))||[];if(credit(m[0],qs[qs.length-1]||'',t,RW,l4))out.push(nr(m[0]));}});return out;}

 const FOLD=x=>String(x==null?'':x).replace(/[‘’ʼ´`]/g,"'").replace(/\[[^\]\n]*:[^\]\n]*\]/g,' ').replace(/[\[\]]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
 function qmatch(q,T){const fr=String(q||'').replace(/^["“]|["”]$/g,'').replace(/\[[^\]\n]*:[^\]\n]*\]/g,' ').split(/\.\.\.|…/).map(FOLD).filter(Boolean);const fl=fr.filter(f=>f.split(' ').length>=2);if(!fl.length)return false;const H=' '+FOLD(T)+' ';return fr.every(f=>H.includes(' '+f+' '));}
 function rowsOf(ref,after,RW){if(!RW||!RW.size)return null;const m=nr(ref).match(/^(.*\S)\s+(\d{1,3}):(\d{1,3})$/);if(!m)return null;let b=m[1].replace(/\.$/,'');if(b==='Psalm')b='Psalms';const v0=+m[3];const rg=String(after||'').match(/^\s*[-–]\s*(\d{1,3})\b(?!:\d)/);const v1=rg&&+rg[1]>v0&&+rg[1]-v0<=30?+rg[1]:v0;const T=[];for(let v=v0;v<=v1;v++){const x=RW.get(b+' '+m[2]+':'+v);if(x==null)return null;T.push(x);}return T.join(' ');}
 function credit(ref,q,after,RW,l4){const T=rowsOf(ref,after,RW);if(T===null)return !l4;return qmatch(q,T);}
 function sheet(){const M=new Map();if(typeof $!=='function')return M;const rd=f=>{try{const x=f();return x&&x.isExecuted?x.all().map(i=>i.json):[];}catch(e){return [];}};
  for(const r of [].concat(rd(()=>$('D1 Verse Sheet')),rd(()=>$('C1 Verse Sheet')),rd(()=>$('D2 Verse Sheet')),rd(()=>$('C2 Verse Sheet')),rd(()=>$('D3 Verse Sheet')),rd(()=>$('C3 Verse Sheet')),rd(()=>$('D4 Verse Sheet')),rd(()=>$('C4 Verse Sheet'))))if(r&&r.book&&r.text!=null&&r.chapter!=null&&r.verse!=null)M.set(r.book+' '+r.chapter+':'+r.verse,String(r.text));return M;}
 function inherit(x){let cur=null,ci=0,cb=false;return x.split('\n').map(l=>{const ind=(l.match(/^\s*/)||[''])[0].length,bul=/^\s*[-*•]\s/.test(l),t=l.match(/^\s*(?:[-*•]\s+)?[*_]*\[L([1-4])\]/);
   if(t){cur=t[1];ci=ind;cb=bul;return l;}if(!l.trim()||!bul){cur=null;return l;}if(cur&&/\[L[1-4]\]/.test(l)===false&&(ind>ci||!cb))return l.replace(/^(\s*[-*•]\s+)/,'$1[L'+cur+'] ');return l;}).join('\n');}  
 function verses(x,Q,RW){const S=new Map();let noref=0;x=inherit(x);
   for(const l of x.split('\n')){if(Q&&BK.test(l)&&!CR.test(l))for(const seg of l.split(/(?=\[L[1-4]\])/)){const t=seg.match(/^\[L([13])\]/);if(!t||QO.test(seg)||!BK.test(seg))continue;for(const m of seg.matchAll(R1)){if(/^\s*(?:[-–—]\s*\d|,\s*\d)/.test(seg.slice(m.index+m[0].length)))continue;const v=nr(m[0]);if(Q.has(v))S.set(v,(S.get(v)||'')+t[1]);}}  
    if(!QO.test(l)||CR.test(l))continue;const l4=/^[\s*_>-]*\[L4\]/.test(l);let m=l.match(ANS)||l.match(MR);if(m){const ai=l.indexOf(m[1])+m[1].length;if(credit(m[1],(l.slice(ai).match(QO)||[''])[0],l.slice(ai),RW,false))S.set(nr(m[1]),(S.get(nr(m[1]))||'')+'1');}
    const parts=l.split(/(?=\[L[1-4]\])/);for(const seg of parts){const t=seg.match(/^\[L([1-4])\]/);if(!t||(t[1]!=='1'&&t[1]!=='3'))continue;const r=paired(seg,RW,l4);if(!r.length){if(QO.test(seg)&&!R1.test(seg))noref++;R1.lastIndex=0;continue;}r.forEach(v=>S.set(v,(S.get(v)||'')+t[1]));}
    const pw=l.search(/PRESSED WITH\s*:/i);if(pw>=0)paired(l.slice(pw),RW,false).forEach(v=>S.set(v,(S.get(v)||'')+'1'));  
    let last=0;for(const g of l.matchAll(/\(([^()\n]*\[L[13]\][^()\n]*)\)/g)){const qs=[...l.slice(last,g.index).matchAll(new RegExp(QO.source,'g'))].map(x=>x[0]);const q=qs.length;last=g.index+g[0].length;let c=0;
     for(const sg of g[1].split(';')){const tg=sg.match(/\[L([13])\]\s*$/);if(!tg||tg[1]!=='1')continue;for(const r of (sg.match(R1)||[])){const T=rowsOf(r,'',RW);if(T!==null){if(qs.some(x=>qmatch(x,T)))S.set(nr(r),(S.get(nr(r))||'')+'1');continue;}if(c>=q||l4)break;S.set(nr(r),(S.get(nr(r))||'')+'1');c++;}R1.lastIndex=0;}}  
   }
   return {n:S.size,l1:[...S.values()].some(v=>v.includes('1')),noref,refs:new Set(S.keys())};}
 function structure(t,RW){if(RW===undefined)RW=sheet();const L=String(t||'').split('\n');const B=[];let cur=null;const Q=verses(String(t||''),null,RW).refs;  
   for(const l of L){if(CP.test(l)||MD.test(l)){if(cur)B.push(cur);cur=CP.test(l)?{head:l.trim(),lines:[l]}:null;continue;}if(cur)cur.lines.push(l);}if(cur)B.push(cur);
   const out=[];B.forEach(b=>{const x=b.lines.join('\n');if(x.replace(/\s+/g,' ').trim().length<60)return;if(WD.test(b.head)&&!WDN.test(b.head))return;if(RECAP.test(b.head))return;    const v=verses(x,Q,RW);if(v.n>=2&&v.l1)return;if(absent(x))return;  

    out.push({kind:'STRUCTURE',head:b.head.slice(0,300),why:(v.n===0?'no verse quoted with its reference on an [L1] or [L3] line':v.n===1?'one verse only on its layer lines; no further verse is read with it on an [L1] or [L3] line':'no [L1] verse among its layer lines')+(v.noref?'; '+v.noref+' tagged verse(s) quoted with no reference on the line (state the reference)':'')});});return out;}
