const cecBlock=function(T,q){ T=String(T||'');const U=T.replace(/[\u2018\u2019]/g,"'");const ws=String(q||'').replace(/[\u2018\u2019]/g,"'").replace(/[*_]+/g,'').match(/[A-Za-z0-9\u00C0-\u024F\u1E00-\u1FFF']+/g)||[];if(ws.length<3)return '';const re=new RegExp(ws.map(x=>x.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('[^A-Za-z0-9\u00C0-\u024F\u1E00-\u1FFF\']+'),'g');const hs=[...U.matchAll(re)];if(!hs.length)return '';const m=hs.find(h=>!/["\u201C']\s*[*_]*\s*$/.test(U.slice(Math.max(0,h.index-3),h.index)))||hs[0];const i=m.index;const H=/^[ \t>]*(?:#{1,6}\s|\*\*(?!\s*\[L\d)[^\n]{2,}?\*\*[ \t]*:?[ \t]*$|(?:\*\*)?(?:LINK\s+\d|ANSWER\s*:|(?:[CD]\d+|X\d+)\s*[:.-]))/,G=/^[ \t>]*\*\*(?!\s*\[L\d)[^\n]{2,}?\*\*/;
