const lk=sd=>links[sd].length?links[sd].map(n=>(sd==='DEFENDER'?'D':'C')+n+' = LINK '+n).join(', '):'(none read)';
const __cb=new Map();const cl=cands.length?cands.map(c=>c.id+' -- '+c.side+' -- '+c.kind+' '+c.n+' -- EARLIER ['+c.earlier_round+'] "'+c.earlier_q+'" -- CLOSING ['+c.closing_round+'] "'+c.closing_q+'" -- named by '+c.by+(c.why?': '+c.why:'')+(()=>{const k=c.closing_round+'|'+c.closing_q;if(__cb.has(k))return '\n   CLOSING BLOCK: as under '+__cb.get(k)+'.';const b=cecBlock(F[CEC_RK[c.closing_round]],c.closing_q);if(b)__cb.set(k,c.id);return b?'\n   CLOSING BLOCK (the closing sentence with the rows of its block, ['+c.closing_round+']):\n   '+b.replace(/\n/g,'\n   '):'';})()).join('\n'):'none';  
const user=PROMPT+'\n\nCANDIDATES ALREADY NAMED (answer each one by its id):\n'+cl
 +'\n\n######## THE DEFENDER ########\nThe defender\'s links: '+lk('DEFENDER')+' (its DECLARED CHAIN in [CR1]). Its closing round is [CR4].\n\n'+[['CR1','cr1'],['CR2','cr2'],['CR3','cr3'],['CR4 -- THE DEFENDER\'S CLOSING ROUND','cr4']].map(x=>R(x[0],x[1])).join('\n\n')
 +'\n\n######## THE CHALLENGER ########\nThe challenger\'s links: '+lk('CHALLENGER')+' (its LINK blocks in [DR3]). Its closing round is [DR4].\n\n'+[['DR1','gr1'],['DR2','gr2'],['DR3','dr3'],['DR4 -- THE CHALLENGER\'S CLOSING ROUND','dr4']].map(x=>R(x[0],x[1])).join('\n\n');
const body={model:ds.api_model,max_tokens:Math.max(Number(ds.max_tokens)||0,16000),temperature:0,messages:[{role:'system',content:'You check each debater against its own earlier words. You bring nothing from outside the words given to you: no doctrine, no training knowledge, no reading of your own. You do not judge who is right, and you do not judge one side by the other side\'s words.'},{role:'user',content:user}]};
return [{json:{cec_skip:false,cands_only:true,answered_before,body,links,cands,missing_rounds:miss,model:ds.api_model,run_token:S.run_token,copy:1}},{json:{cec_skip:false,cands_only:true,answered_before,body:{...body,temperature:0.6},links,cands,missing_rounds:miss,model:ds.api_model,run_token:S.run_token,copy:2}}];  
}catch(__e){let __rt=null;try{__rt=$('Init Seats').first().json.run_token||null;}catch(e){}return [{json:{cec_skip:true,why:'Judge Contradiction Build failed: '+String(__e&&__e.message||__e).slice(0,300),run_token:__rt}}];}

